#!/usr/bin/env python3
"""Single-run live aircraft -> red runway poster. Python 3.8+."""
import base64
import getpass
import os
import io
import json
import math
from pathlib import Path
import time
import urllib.error
import urllib.parse
import urllib.request
import zlib

try:
    from PIL import Image, ImageDraw, ImageFont
except ImportError:
    print('Pillow is missing. Use: ~/flight-tracker-env/bin/python -m pip install Pillow==10.4.0')
    print('Then run this file again.')
    raise SystemExit(1)

TEMPLATE_DATA = """"""
LAT, LON, RADIUS_KM = -33.8830, 151.2065, 5.0
MIN_INTEREST_SCORE = 0.0  # All identifiable airborne flights within 5 km are eligible.
TOKEN_URL = 'https://auth.opensky-network.org/auth/realms/opensky-network/protocol/openid-connect/token'
STATES_URL = 'https://opensky-network.org/api/states/all?lamin=-33.94&lamax=-33.82&lomin=151.13&lomax=151.28'
HEADERS = {'User-Agent': 'ChrisFlightPoster/2.0'}
RED = (159, 52, 48)
CREAM = (247, 242, 229)


def fetch_json(url, data=None, headers=None):
    req = urllib.request.Request(url, data=data, headers=headers or HEADERS)
    with urllib.request.urlopen(req, timeout=30) as response:
        return json.load(response)


def distance_km(lat, lon):
    p1, p2 = math.radians(LAT), math.radians(lat)
    dp, dl = p2-p1, math.radians(lon-LON)
    a = math.sin(dp/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 12742*math.asin(min(1, math.sqrt(a)))


def metadata(icao):
    try:
        data = fetch_json('https://api.adsb.lol/v2/hex/' + urllib.parse.quote(icao))
        return next((r for r in data.get('ac', []) if str(r.get('hex', '')).lower() == icao.lower()), {})
    except (OSError, ValueError, KeyError):
        return {}


def interest(distance, model):
    bonuses = {'A388': 40, 'B748': 40, 'B744': 40, 'A346': 30,
               'A359': 25, 'A35K': 25, 'B77W': 25, 'B789': 20, 'B788': 20}
    return (5-distance)*10 + bonuses.get((model or '').upper(), 0)


def readable_model(code, description):
    names = {'B788':'BOEING 787-8', 'B789':'BOEING 787-9',
             'B78X':'BOEING 787-10', 'A388':'AIRBUS A380',
             'A359':'AIRBUS A350-900', 'A35K':'AIRBUS A350-1000',
             'B77W':'BOEING 777-300ER', 'B748':'BOEING 747-8',
             'B744':'BOEING 747-400', 'DH8D':'DASH 8 Q400',
             'B350':'KING AIR 350'}
    return names.get((code or '').upper(), (description or code or 'AIRCRAFT').upper())


def airline_label(operator, callsign, registration):
    labels = {'TGW':'SCOOT', 'QLK':'QANTASLINK', 'QFA':'QANTAS',
              'VOZ':'VIRGIN AUSTRALIA', 'JST':'JETSTAR', 'RXA':'REX',
              'UAE':'EMIRATES', 'SIA':'SINGAPORE AIRLINES',
              'ANZ':'AIR NEW ZEALAND', 'CPA':'CATHAY PACIFIC',
              'QTR':'QATAR AIRWAYS', 'ETD':'ETIHAD'}
    prefix = callsign[:3].upper()
    if prefix in labels:
        return labels[prefix]
    if operator and operator.strip().lower() not in ('unknown','n/a'):
        return operator.strip().upper()
    # A registration is factual; 'PRIVATE AIRCRAFT' would be an unverified claim.
    return registration.upper() if registration and registration != 'unknown' else 'AIRCRAFT'


def choose_font(size):
    candidates = (
        '/System/Library/Fonts/Supplemental/Andale Mono.ttf',
        '/System/Library/Fonts/Supplemental/Courier New Bold.ttf',
        '/Library/Fonts/Courier New Bold.ttf',
        '/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf',
        '/usr/share/fonts/truetype/liberation/LiberationMono-Bold.ttf',
    )
    for candidate in candidates:
        try:
            return ImageFont.truetype(candidate, size)
        except (OSError, IOError):
            pass
    return ImageFont.load_default()


def draw_fitted(draw, text, center_x, top, max_width, max_size, min_size=11, tracking=1.2):
    text = str(text).upper()
    for size in range(max_size, min_size-1, -1):
        f = choose_font(size)
        spacing = min(tracking, size * .07)
        widths = [draw.textlength(ch, font=f) for ch in text]
        total = sum(widths) + max(0,len(text)-1)*spacing
        if total <= max_width:
            x = center_x-total/2
            for ch, w in zip(text, widths):
                draw.text((round(x), top), ch, font=f, fill=CREAM)
                x += w+spacing
            return size
    # Last-resort truncation prevents overflow with unusually long operator names.
    f = choose_font(min_size)
    while text and draw.textlength(text, font=f) > max_width:
        text = text[:-1]
    draw.text((round(center_x-draw.textlength(text, font=f)/2), top), text, font=f, fill=CREAM)
    return min_size


def make_poster(a, output):
    original = zlib.decompress(base64.b64decode(TEMPLATE_DATA))
    im = Image.open(io.BytesIO(original)).convert('RGB')
    if im.size != (480,800):
        raise ValueError('Unexpected poster dimensions')
    # Remove old Canva lettering without touching the runway graphic.
    d = ImageDraw.Draw(im)
    d.rectangle((12, 76, 196, 280), fill=RED)
    pix = im.load()
    # Rebuild the solid red wedge one scanline at a time. The Canva text is
    # embedded in the background image, so merely painting over light pixels
    # leaves antialiasing ghosts. Redraw the entire interior instead.
    for y in range(641, 800):
        red = []
        for x in range(480):
            r, g, b = pix[x, y]
            red.append(r > g * 1.7 and r > b * 1.7 and r < 210)
        left = next((x for x in range(0, 238) if all(red[x+k] for k in range(3))), None)
        right = next((x for x in range(479, 241, -1) if all(red[x-k] for k in range(3))), None)
        if left is None or right is None or right-left < 50:
            continue
        sample = pix[left+5, y]
        for x in range(left+3, right-2):
            pix[x, y] = sample
    d = ImageDraw.Draw(im)
    # Upper-left typography, kept entirely left of the runway.
    draw_fitted(d,'FLIGHT NO.', 103, 80, 163, 20)
    draw_fitted(d,a['callsign'], 103, 108, 163, 21)
    draw_fitted(d,'ALTITUDE', 103, 153, 163, 20)
    draw_fitted(d,a['altitude'], 103, 182, 163, 21)
    draw_fitted(d,'SEEN AT', 103, 224, 163, 20)
    draw_fitted(d,a['seen_at'], 103, 252, 163, 21)
    # The lower wedge is wider at the airline line than at the model line.
    draw_fitted(d,a['model'], 240, 657, 183, 17, 11, 1.3)
    draw_fitted(d,a['airline'], 240, 704, 255, 31, 13, 1.6)
    im.save(str(output), 'PNG')


def main():
    import sys
    output = Path(os.environ.get('POSTER_OUTPUT', str(Path.home() / 'Downloads' / 'Chris_Flight_Poster.png')))
    if '--demo' in sys.argv:
        make_poster({'callsign':'TGW42', 'altitude':'800 FT',
                     'seen_at':'6:37 PM', 'model':'BOEING 787-8',
                     'airline':'SCOOT'}, output)
        print('Demo poster created: {}'.format(output))
        print('Demo uses earlier observed aircraft data; no live request was made.')
        return
    print('CHRIS FLIGHT POSTER — LIVE AIRCRAFT CHECK')
    print('Central Station / 5 km / airborne aircraft / minimum interest score {}'.format(MIN_INTEREST_SCORE))
    client_id = os.environ.get('OPENSKY_CLIENT_ID') or input('OpenSky client ID: ').strip()
    secret = os.environ.get('OPENSKY_CLIENT_SECRET') or getpass.getpass('OpenSky client secret (hidden): ')
    try:
        token = fetch_json(TOKEN_URL, data=urllib.parse.urlencode({
            'grant_type':'client_credentials', 'client_id':client_id,
            'client_secret':secret}).encode(), headers={
            'Content-Type':'application/x-www-form-urlencoded', **HEADERS})['access_token']
    except (OSError, ValueError, KeyError) as e:
        print('Authentication failed: {}'.format(type(e).__name__))
        return
    del secret
    print('Authentication successful. Checking live aircraft...')
    try:
        data = fetch_json(STATES_URL, headers={'Authorization':'Bearer '+token, **HEADERS})
    except (OSError, ValueError) as e:
        print('Aircraft request failed: {}'.format(type(e).__name__))
        return
    states = data.get('states') or []
    print('OpenSky returned {} aircraft state records in the search area.'.format(len(states)))
    candidates = []
    grounded = 0
    invalid_position = 0
    slow = 0
    outside_radius = 0
    unidentified = 0
    for s in states:
        if len(s) < 10 or s[5] is None or s[6] is None:
            invalid_position += 1
            continue
        if s[8]:
            grounded += 1
            continue
        if s[9] is None or s[9] * 3.6 < 80:
            slow += 1
            continue
        dist = distance_km(s[6], s[5])
        if dist > RADIUS_KM:
            outside_radius += 1
            continue
        callsign = (s[1] or '').strip()
        if not callsign:
            unidentified += 1
            continue
        candidates.append({'icao': s[0], 'callsign': callsign,
                           'distance': dist, 'altitude_m': s[7]})
    print('Filtered: {} grounded, {} missing position, {} slow/unknown speed, '
          '{} outside 5 km, {} missing callsign.'.format(
              grounded, invalid_position, slow, outside_radius, unidentified))
    for a in candidates:
        m=metadata(a['icao'])
        a['model_code']=(m.get('t') or '').strip()
        a['model']=readable_model(a['model_code'], (m.get('desc') or '').strip())
        a['registration']=(m.get('r') or 'unknown').strip()
        a['operator']=(m.get('ownOp') or '').strip()
        a['score']=interest(a['distance'],a['model_code'])
    print('{} eligible airborne aircraft within 5 km.'.format(len(candidates)))
    if not candidates:
        print('No poster created: no identifiable airborne flights in the 5 km area at this snapshot.')
        return
    winner=max(candidates,key=lambda a:a['score'])
    from datetime import datetime
    try:
        from zoneinfo import ZoneInfo
        now = datetime.now(ZoneInfo('Australia/Sydney'))
    except ImportError:
        now = datetime.now()  # Python 3.8 fallback: uses the computer's local timezone
    seen_at='{}:{:02d} {}'.format(now.tm_hour%12 or 12,now.tm_min,'AM' if now.tm_hour<12 else 'PM')
    altitude='UNKNOWN' if winner['altitude_m'] is None else '{:,} FT'.format(round(winner['altitude_m']*3.28084))
    make_poster({'callsign':winner['callsign'],'altitude':altitude,
                 'seen_at':seen_at,'model':winner['model'],
                 'airline':airline_label(winner['operator'],winner['callsign'],winner['registration'])},output)
    print('Selected: {} | {} | {} | {:.2f} km | score {:.1f}'.format(
        winner['callsign'],winner['registration'],winner['model'],winner['distance'],winner['score']))
    print('Created poster: {}'.format(output))
    if os.environ.get('GENERATE_DISPLAY_BIN') == '1':
        im = Image.open(str(output)).convert('RGB')
        if im.size != (480, 800):
            raise ValueError('Expected 480x800 poster, got {}'.format(im.size))
        raw = bytearray()
        pixels = im.load()
        for y in range(800):
            for x0 in range(0, 480, 8):
                byte = 0
                for bit in range(8):
                    r, g, b = pixels[x0 + bit, y]
                    if r + g + b > 550:
                        byte |= 1 << (7 - bit)
                raw.append(byte)
        bin_path = output.with_suffix('.bin')
        bin_path.write_bytes(raw)
        print('Created display bitmap: {} ({} bytes)'.format(bin_path, len(raw)))
    print('Single snapshot complete. Screen refresh timing is controlled by ESP32 firmware.')

if __name__=='__main__':
    main()
